package com.tripcraft.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.*;
@Service public class ImageStorageService {private final Path root;public ImageStorageService(@Value("${app.upload-dir:uploads}")String dir){root=Paths.get(dir).toAbsolutePath().normalize();}public String store(MultipartFile file)throws IOException{String type=Optional.ofNullable(file.getContentType()).orElse("").toLowerCase();if(!Set.of("image/jpeg","image/png","image/webp").contains(type))throw new IllegalArgumentException("Only JPG, PNG and WebP images are accepted");if(file.getSize()>2_000_000)throw new IllegalArgumentException("Image must be 2 MB or smaller");String ext=type.equals("image/png")?".png":type.equals("image/webp")?".webp":".jpg";Files.createDirectories(root);String name=UUID.randomUUID()+ext;Files.copy(file.getInputStream(),root.resolve(name),StandardCopyOption.REPLACE_EXISTING);return "/uploads/"+name;}}
